import io
import json
import pandas as pd


def read_sales(text):
    df = pd.read_csv(io.StringIO(text))
    sales = []
    for row in df.to_dict('records'):
        sales.append({
            'product': row['product'],
            'quantity': int(row['quantity']),
            'price': float(row['price']),
        })
    return sales


def totals(sales):
    by_product = {}
    for sale in sales:
        product = sale['product']
        money = int(sale['quantity']) * float(sale['price'])
        by_product[product] = by_product.get(product, 0.0) + money
    return {product: float(money) for product, money in by_product.items()}


def save_report(path, sales):
    by_product = {str(product): float(money) for product, money in totals(sales).items()}
    total = float(sum(by_product.values()))
    best = max(by_product, key=by_product.get) if by_product else None
    report = {
        'total': total,
        'by_product': by_product,
        'best': best,
    }
    with open(path, 'w', encoding='utf-8') as file:
        json.dump(report, file)


def load_report(path):
    with open(path, 'r', encoding='utf-8') as file:
        return json.load(file)

